-- Drop existing companies table to ensure schema matches
DROP TABLE IF EXISTS companies CASCADE;

-- Create companies table
CREATE TABLE companies (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  name text NOT NULL,
  sector text NOT NULL,
  category text,
  street text,
  city text,
  country text DEFAULT 'GH',
  phone text,
  website text,
  google_maps_url text,
  image_url text,
  rating numeric,
  reviews_count integer,
  lat double precision,
  lng double precision,
  opportunity_types text[] DEFAULT '{attachment, internship, job}',
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE companies ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read access on companies" ON companies;
CREATE POLICY "Allow public read access on companies" ON companies FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow authenticated insert on companies" ON companies;
CREATE POLICY "Allow authenticated insert on companies" ON companies FOR INSERT WITH CHECK (true);

